material.script:
function memList(store){
  try{
    var a = JSON.parse(store.mems || "[]");
    return Array.isArray(a) ? a : [];
  }catch(e){ return []; }
}

function memNorm(s){ return String(s || "").replace(/\s+/g, " ").trim(); }
function memPad(n){ return (n < 10 ? "0" : "") + n; }
function memNow(){ var d = new Date(); return memPad(d.getHours()) + ":" + memPad(d.getMinutes()); }

function memStart(e){ return e.from || e.turn || 0; }
function memEnd(e){ return e.to || e.turn || 0; }

function memMax(list){
  var mx = 0;
  for(var i = 0; i < list.length; i++){
    var t = memEnd(list[i]);
    if(t > mx) mx = t;
  }
  return mx;
}

function memKey(s){
  return memNorm(s).replace(/[\s，。、；：""''！？…—·,.;:!?()（）\[\]【】「」『』]/g, "").slice(0, 14);
}

function memDup(a, b){
  var ka = memKey(a), kb = memKey(b);
  if(!ka || !kb) return false;
  if(ka === kb) return true;
  var n = Math.min(ka.length, kb.length);
  if(n >= 6 && (ka.indexOf(kb.slice(0, 6)) >= 0 || kb.indexOf(ka.slice(0, 6)) >= 0)) return true;
  return false;
}

function memCut(s, n){
  var t = memNorm(s);
  if(!t) return "";
  return t.length > n ? t.slice(0, n) + "…" : t;
}

function memNone(s){
  var t = memNorm(s);
  if(t === "无" || t === "無" || t === "暂无" || t === "-") return "";
  return t;
}

function memClearCompress(store){
  store.compressPending = false;
  store.compressIds = [];
  store.compressTurn = 0;
}

function memClearBackfill(store){
  store.backfillPending = false;
  store.backfillTurn = 0;
}

function memExpire(store, turn){
  if(store.compressPending && (store.compressTurn || 0) < turn) memClearCompress(store);
  if(store.backfillPending && (store.backfillTurn || 0) < turn) memClearBackfill(store);
}

var MEM_OPEN = "[\\[［【]\\s*记忆\\s*(?:[：:][^\\]］】]*)?[\\]］】]";
var MEM_CLOSE = "[\\[［【]\\s*\\/\\s*记忆\\s*[\\]］】]";

function memExtract(raw){
  var re = new RegExp(MEM_OPEN + "([\\s\\S]*?)" + MEM_CLOSE, "g");
  var bodies = [];
  var empty = false;
  var m;
  while((m = re.exec(raw)) !== null){
    var body = m[1] || "";
    if(memNorm(body) === "-"){ empty = true; continue; }
    bodies.push(body);
  }

  var rest = raw.replace(re, "");

  var openRe = new RegExp(MEM_OPEN, "g");
  var om = openRe.exec(rest);
  if(om){
    var tail = rest.slice(om.index + om[0].length);
    if(/\||事件\s*[：:]|关系\s*[：:]|细节\s*[：:]|关键词\s*[：:]|轮次\s*[：:]/.test(tail)){
      bodies.push(tail);
      rest = rest.slice(0, om.index);
    }else{
      rest = rest.replace(new RegExp(MEM_OPEN, "g"), "");
    }
  }
  rest = rest.replace(new RegExp(MEM_CLOSE, "g"), "");

  return { bodies: bodies, rest: rest, empty: empty };
}

function memParseBody(body){
  var t = String(body || "").trim();
  if(!t) return null;

  if(t.indexOf("|") >= 0){
    var flat = t.replace(/\s*\n\s*/g, " ");
    var f = flat.split("|");
    for(var i = 0; i < f.length; i++) f[i] = memNorm(f[i]);

    var kind = "normal", from = 0, to = 0, off = 0;

    if(f[0] === "压缩" || f[0] === "压缩件" || f[0] === "已压缩" || f[0] === "合并"){
      kind = "compress";
      var rr = f[1] || "";
      var rm = rr.match(/(\d+)\s*[-~—－到至]\s*(\d+)/);
      if(rm){ from = parseInt(rm[1], 10); to = parseInt(rm[2], 10); }
      else { var r1 = rr.match(/(\d+)/); if(r1){ from = to = parseInt(r1[1], 10); } }
      off = 2;
    }else if(/^\d+$/.test(f[0])){
      from = to = parseInt(f[0], 10);
      off = 1;
    }

    var ev = memNorm(f[off] || "");
    if(!ev) return null;

    return {
      kind: kind,
      from: from,
      to: to,
      event: memCut(ev, 90),
      rel: memNone(f[off + 1] || ""),
      detail: memNone(f[off + 2] || ""),
      kw: memNone(f[off + 3] || "")
    };
  }

  var lines = t.split(/\r?\n/);
  var ev2 = "", rel2 = "", det2 = "", kw2 = "", fr2 = 0, to2 = 0;
  var isComp = /压缩|合并/.test(t);

  for(var li = 0; li < lines.length; li++){
    var L = memNorm(lines[li]);
    if(!L) continue;
    var tm = L.match(/^(?:轮次|第\s*\d+\s*轮)\s*[：:]\s*([\d\-~—－到至]+)/);
    var em = L.match(/^事件\s*[：:]\s*(.+)$/);
    var rm2 = L.match(/^关系\s*[：:]\s*(.+)$/);
    var dm = L.match(/^细节\s*[：:]\s*(.+)$/);
    var km = L.match(/^关键词\s*[：:]\s*(.+)$/);
    if(tm){
      var rr2 = tm[1];
      var rrm = rr2.match(/(\d+)\s*[-~—－到至]\s*(\d+)/);
      if(rrm){ fr2 = parseInt(rrm[1], 10); to2 = parseInt(rrm[2], 10); }
      else { var r11 = rr2.match(/(\d+)/); if(r11){ fr2 = to2 = parseInt(r11[1], 10); } }
    }
    else if(em) ev2 = memNorm(em[1]);
    else if(rm2) rel2 = memNorm(rm2[1]);
    else if(dm) det2 = memNorm(dm[1]);
    else if(km) kw2 = memNorm(km[1]);
    else if(!ev2) ev2 = L;
  }

  if(!ev2) return null;

  return {
    kind: isComp ? "compress" : "normal",
    from: fr2,
    to: to2,
    event: memCut(ev2, 90),
    rel: memNone(rel2),
    detail: memNone(det2),
    kw: memNone(kw2)
  };
}

function memFmt(e){
  var label = e.kind === "compress"
    ? "（第" + (e.from || e.turn || "?") + "-" + (e.to || e.turn || "?") + "轮·压缩）"
    : "（第" + (e.turn || "?") + "轮）";
  var s = label + memCut(e.event, 120);
  var extra = [];
  if(e.rel) extra.push(memCut(e.rel, 60));
  if(e.detail) extra.push(memCut(e.detail, 60));
  if(extra.length) s += " —— " + extra.join("；");
  return s;
}

function onBeforeSend(ctx){
  var store = ctx.store || {};
  var turn = (ctx.turnCount || 0) + 1;


  memExpire(store, turn);
  store.lastTurn = turn;

  var list = memList(store);


  var AUTO_TRIGGER = parseInt(store.compressTrigger, 10);
  if(isNaN(AUTO_TRIGGER) || AUTO_TRIGGER < 1) AUTO_TRIGGER = 60;
  var AUTO_BATCH = parseInt(store.compressBatch, 10);
  if(isNaN(AUTO_BATCH) || AUTO_BATCH < 1) AUTO_BATCH = 20;
  if(!store.compressPending && !store.backfillPending && (!(store.compressFail) || (turn - store.compressFail) > 3)){
    var _normals = [];
    for(var _ni = 0; _ni < list.length; _ni++){
      if(list[_ni].kind !== "compress" && !list[_ni].pinned) _normals.push(list[_ni]);
    }
    if(_normals.length >= AUTO_TRIGGER){
      _normals.sort(function(a, b){ return memStart(a) - memStart(b); });
      var _take = _normals.slice(0, Math.min(AUTO_BATCH, _normals.length));
      var _ids = [];
      for(var _ti = 0; _ti < _take.length; _ti++) _ids.push(_take[_ti].id);
      store.compressPending = true;
      store.compressIds = _ids;
      store.compressTurn = turn;
    }
  }

  var win = parseInt(store.recallN, 10);
  if(isNaN(win) || win < 0) win = 8;

  var cutoff = turn - win;

  var sections = [];
  var busy = !!store.compressPending || !!store.backfillPending;

  if(!busy){

    var pool = [];
    for(var i = 0; i < list.length; i++){
      if(memEnd(list[i]) < cutoff) pool.push(list[i]);
    }

    if(pool.length > 0){

      var pinned = [];
      var restMem = [];
      for(var c = 0; c < pool.length; c++){
        if(pool[c].pinned) pinned.push(pool[c]);
        else restMem.push(pool[c]);
      }
      var all = pinned.concat(restMem);
      all.sort(function(a, b){ return memStart(a) - memStart(b); });

      var lines = [];
      for(var a = 0; a < all.length; a++) lines.push(memFmt(all[a]));

      var body = "## 往事纪要 · 已归档的全部旧记忆（全量注入）\n"
        + "以下是从长期记忆库检出的、本轮对话之前发生的全部旧事，按时间顺序（「压缩」为多轮合并的梗概）。它们是你和{{user}}之间已经发生的既定事实：称谓、承诺、伤痕、随身物件、地点、秘密、未解决事项与关系进展都必须与之连贯，不得自相矛盾，不得遗忘已经建立的默契或冲突。\n"
        + "它们不一定是刚才发生的事，请只当作过往经历与关系背景参考，不要误当成当前现场；也不要复述、总结或罗列，只让它们自然影响人物此刻的言行。\n"
        + lines.join("\n")
        + "\n\n【重要】这些只是背景。禁止改写成剧情写进正文或状态栏，也禁止为这些旧轮次重新输出记忆块。";

      sections.push({ at: "world", text: body });
    }
  }

  var note;

  if(store.compressPending){
    var ids = store.compressIds || [];
    var targets = [];
    for(var ti = 0; ti < list.length; ti++){
      if(ids.indexOf(list[ti].id) >= 0) targets.push(list[ti]);
    }
    targets.sort(function(a, b){ return memStart(a) - memStart(b); });

    var tl = [];
    for(var t2 = 0; t2 < targets.length; t2++){
      var e2 = targets[t2];
      var one = "（第" + (e2.from || e2.turn || "?");
      if(e2.to && e2.to !== (e2.from || e2.turn)) one += "-" + e2.to;
      one += "轮）" + (e2.event || "");
      var ex2 = [];
      if(e2.rel) ex2.push(e2.rel);
      if(e2.detail) ex2.push(e2.detail);
      if(ex2.length) one += " —— " + ex2.join("；");
      tl.push(one);
    }

    note = "[系统协议 · 记忆压缩（一次性任务，本轮有效）：正常写本轮正文即可，写完在回复最末尾另起区域完成压缩。\n"
      + "把下面这些旧记忆重新整合：不限定条数，合并重复、舍弃无聊日常与寒暄修辞，只保留高密度长期信息。每条单独一个壳，格式严格：\n[记忆]压缩|起始轮-结束轮|事件|关系|细节|关键词[/记忆]\n"
      + "单条不超过 50 字（不含壳）；轮次范围要覆盖它对应的原始轮次。\n"
      + "保留优先级（字数有限必须取舍时）：①具体物件/称呼/约定/伤痕/秘密/未解决事项（连续性锚点，丢了就接不上）→ ②关系与态度转折、明确心理 → ③时间地点场景、物品状态变化、承诺与计划。舍弃剧情过程描述，只留结果与状态；不得为凑字数删除上述锚点。\n"
      + "压缩完之后，再按常规补一条本轮记忆：\n[记忆]" + turn + "|本轮事件|关系变化|细节|关键词[/记忆]\n"
      + "外壳必须用半角 [记忆] 与 [/记忆]。不要在正文里讨论压缩这件事。\n"
      + "待压缩的旧记忆：\n" + tl.join("\n");
  }else if(store.backfillPending){
    var mxb = memMax(list);
    var bhint = mxb > 1 ? ("第 1 轮到第 " + (mxb - 1) + " 轮") : "你上下文里已有的全部对话";
    note = "[系统协议 · 记忆回溯（一次性任务，本轮有效）：本轮不必推进剧情，只做归档。\n"
      + "请回顾" + bhint + "，把它们提炼成关键记忆：同一段连续剧情合并成一条，琐碎日常、寒暄、重复动作直接舍弃；只保留剧情关键信息、人物关系与处境转折，以及具体物件/约定/伤痕/秘密/未解决事项。\n"
      + "每条单独一个壳，格式严格：\n[记忆]压缩|起始轮-结束轮|事件|关系|细节|关键词[/记忆]\n"
      + "单条不超过 50 字（不含壳），全部条目总量控制在 500 字以内；宁少勿编，只写你确实还记得的内容。关键词必须包含那些不可替代的具体名词。\n"
      + "记忆块之后最多写一句简短过渡，不要展开剧情。外壳必须用半角 [记忆] 与 [/记忆]。";
  }else{
    note = "[系统协议 · 记忆归档（每轮按需记录）：本轮正文写完后，在回复最末尾（若本轮有小剧场，放在小剧场之后）另起一行输出本条：\n"
      + "[记忆]" + turn + "|事件|关系|细节|关键词[/记忆]\n"
      + "字段用竖线分隔：\n"
      + "- 事件：客观概括本轮发生的事实、行动或转折，20~40 字。\n"
      + "- 关系：{{char}}与{{user}}的关系、立场或心态变化，15~30 字；本轮无变化写「无」。\n"
      + "- 细节：只记对后续剧情有影响、且丢了就接不上的具体信息——随身物件与归属、明确承诺/约定、秘密、未解决事项、身体/精神状态、地点与场景，以及人物未说出口的真实想法/欲望/恐惧/意图（注明是内心而非表现）。没有就写「无」。\n"
      + "- 关键词：3~6 个具体短词，顿号分隔，必须包含上面那些不可替代的具体名词（如戒指、约定、伤疤、某地），不要写「我们/什么/然后」这类虚词。\n"
      + "【铁律】1. 只写本轮这一条，轮次固定写 " + turn + "。2. 上文旧记忆是背景，禁止重写、重述或补写任何往期条目，重复输出会被直接丢弃。3. 外壳必须半角 [记忆] 与 [/记忆]，禁止用【】或［］。4. 壳外不要解释。5. 只记本轮新增、确认或发生变化的信息。若本轮确实无任何值得长期记住的新信息，必须单独输出一行空记忆块 [记忆]-[/记忆]（轮次与字段之间只写一个短横、其余留空），不要硬凑其他内容；只要有新增或变化，就必须输出正常的 [记忆] 块。";
  }

  return { sections: sections, note: note, store: store };
}

function onRawReply(ctx){
  var raw = ctx.raw || "";
  var store = ctx.store || {};
  var curTurn = (ctx.turnCount || 0) + 1;


  memExpire(store, curTurn);
  store.lastTurn = curTurn;

  var list = memList(store);
  var mx = memMax(list);

  var got = memExtract(raw);
  var parsed = [];
  for(var b = 0; b < got.bodies.length; b++){
    var obj = memParseBody(got.bodies[b]);
    if(obj) parsed.push(obj);
  }

  var comp = [];
  var norm = [];
  for(var p = 0; p < parsed.length; p++){
    if(parsed[p].kind === "compress") comp.push(parsed[p]);
    else norm.push(parsed[p]);
  }

  var addedComp = 0;
  var addedNorm = 0;

  function pushComp(src){
    for(var q = 0; q < list.length; q++){
      if(memDup(list[q].event, src.event)) return false;
    }
    var fr = src.from || mx + 1;
    var to = src.to || fr;
    if(to < fr){ var tmp = fr; fr = to; to = tmp; }
    list.push({
      id: "m_" + Date.now() + "_" + Math.floor(Math.random() * 100000) + "_c" + addedComp,
      kind: "compress",
      turn: to,
      from: fr,
      to: to,
      event: src.event,
      rel: src.rel,
      detail: src.detail,
      kw: src.kw,
      pinned: false,
      time: memNow()
    });
    addedComp++;
    return true;
  }

  var didCompress = false;
  var didBackfill = false;

  if(store.compressPending){
    if(comp.length){
      var ids = store.compressIds || [];
      var kept = [];
      for(var ki = 0; ki < list.length; ki++){
        if(ids.indexOf(list[ki].id) < 0) kept.push(list[ki]);
      }
      list = kept;
      for(var ci = 0; ci < comp.length; ci++) pushComp(comp[ci]);
      store.compressFail = 0;
      didCompress = true;
    }else{
      store.compressFail = curTurn;
    }

    memClearCompress(store);
    comp = [];
  }
  else if(store.backfillPending){
    if(comp.length){
      for(var bi = 0; bi < comp.length; bi++) pushComp(comp[bi]);
      store.backfillDone = true;
      store.backfillFail = 0;
      didBackfill = true;
    }else{
      store.backfillFail = curTurn;
    }
    memClearBackfill(store);
    comp = [];
  }

  if(norm.length){
    var chosen = null;
    for(var s1 = 0; s1 < norm.length; s1++){
      if(norm[s1].from === curTurn){ chosen = norm[s1]; break; }
    }
    if(!chosen){
      chosen = norm[0];
      for(var s2 = 1; s2 < norm.length; s2++){
        if((norm[s2].from || 0) >= (chosen.from || 0)) chosen = norm[s2];
      }
    }

    var exist = false;
    for(var ek = 0; ek < list.length; ek++){
      if(list[ek].kind !== "compress" && (list[ek].turn || 0) === curTurn){ exist = true; break; }
    }

    if(!exist){
      var dupN = false;
      for(var dq = 0; dq < list.length; dq++){
        if(memDup(list[dq].event, chosen.event)){ dupN = true; break; }
      }
      if(!dupN){
        list.push({
          id: "m_" + Date.now() + "_" + Math.floor(Math.random() * 100000) + "_n",
          kind: "normal",
          turn: curTurn,
          from: curTurn,
          to: curTurn,
          event: chosen.event,
          rel: chosen.rel,
          detail: chosen.detail,
          kw: chosen.kw,
          pinned: false,
          time: memNow()
        });
        addedNorm = 1;
      }
    }
  }

  list.sort(function(a, b){ return memEnd(a) - memEnd(b); });
  if(list.length > 240) list = list.slice(list.length - 240);


  if(addedComp > 0 || addedNorm > 0 || didCompress || didBackfill || parsed.length > 0){
    store.mems = JSON.stringify(list);
  }

  var cleaned = got.rest.replace(/\n{3,}/g, "\n\n").trim();

  return { raw: cleaned, store: store };
}
